#[path="main.rs"] mod fixture;
use anyhow::{Result,ensure};
use sarv_quote::{core::OpeningCommand,store::Store};
use std::{fs,path::{Path,PathBuf},process::{Command,Child,Stdio},io::{Write,Read,BufRead,BufReader},os::unix::process::ExitStatusExt};
fn seed(dir:&Path)->Result<OpeningCommand>{fs::create_dir_all(dir)?;let(s,o)=fixture::fixture()?;let mut store=Store::open(dir)?;store.change(|st|{st.accounting=s;Ok(())})?;fs::write(dir.join("opening.json"),serde_json::to_vec(&o)?)?;Ok(o)}
fn ready(phase:&str)->Result<()> {println!("READY {phase}");std::io::stdout().flush()?;std::io::stdin().read_exact(&mut[0u8;1])?;Ok(())}
fn worker(dir:&Path,phase:&str,key:&str)->Result<()> {let mut store=Store::open(dir)?;let(g,mut state)=store.begin_detached()?;let mut o:OpeningCommand=serde_json::from_slice(&fs::read(dir.join("opening.json"))?)?;o.request_key=key.into();let jid=state.accounting.post_opening(o)?;let prep=Store::prepare_candidate(g,state)?;ready("candidate validated")?;match Store::commit_detached(dir.into(),prep){Ok(_)=>{println!("COMMITTED {jid}");if phase=="after" {ready("after durable commit before adoption")?;}},Err(e)=>println!("CONFLICT {e}")};Ok(())}
fn child(dir:&Path,phase:&str,key:&str)->Result<(Child,BufReader<std::process::ChildStdout>)>{let mut c=Command::new(std::env::current_exe()?).args(["worker",dir.to_str().unwrap(),phase,key]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::inherit()).spawn()?;let mut r=BufReader::new(c.stdout.take().unwrap());let mut line=String::new();r.read_line(&mut line)?;ensure!(line.starts_with("READY"),"worker ready: {line}");Ok((c,r))}
fn go(c:&mut Child)->Result<()> {c.stdin.as_mut().unwrap().write_all(b"G")?;c.stdin.as_mut().unwrap().flush()?;Ok(())}
fn check(dir:&Path,count:usize)->Result<()> {let s=Store::open(dir)?;s.state.validate()?;ensure!(s.state.accounting.core.openings.len()==count&&s.state.accounting.journals.len()==count,"old or complete opening");if count==1 {let o=&s.state.accounting.core.openings[0].command;let p=s.state.accounting.reconcile_opening(&o.company_id,&o.as_of)?;ensure!(p.total_debit.rials()==1251&&p.total_credit.rials()==1251&&p.reconciled,"complete literal1251 controls");}let db=rusqlite::Connection::open(dir.join("sarv.sqlite3"))?;let integrity:String=db.query_row("PRAGMA integrity_check",[],|r|r.get(0))?;ensure!(integrity=="ok","integrity");Ok(())}
fn main()->Result<()> {let args:Vec<_>=std::env::args().collect();if args.get(1).map(String::as_str)==Some("worker"){return worker(Path::new(&args[2]),&args[3],&args[4]);}let root=PathBuf::from(args.get(1).cloned().unwrap_or("/tmp/m3-atomic-review".into()));fs::create_dir_all(&root)?;
 for (name,same) in [("same-key",true),("different-key",false)] {let d=root.join(name);let o=seed(&d)?;let(mut a,mut ar)=child(&d,"normal","parallel-key-a")?;let(mut b,mut br)=child(&d,"normal",if same {"parallel-key-a"}else{"parallel-key-b"})?;go(&mut a)?;go(&mut b)?;let mut al=String::new();let mut bl=String::new();ar.read_to_string(&mut al)?;br.read_to_string(&mut bl)?;ensure!(a.wait()?.success()&&b.wait()?.success(),"workers normal");ensure!(al.contains("COMMITTED")!=bl.contains("COMMITTED"),"one durable winner {al} / {bl}");check(&d,1)?;let mut s=Store::open(&d)?;let id=s.state.accounting.journals[0].id.clone();s.change(|st|{let mut retry=o;retry.request_key="parallel-key-b".into();ensure!(st.accounting.post_opening(retry)?==id,"loser retry id");Ok(())})?;check(&d,1)?;println!("PASS concurrency {name}: one CAS winner, one conflict, reopened retry one opening"); }
 for (name,after) in [("kill-before",false),("kill-after",true)]{let d=root.join(name);seed(&d)?;let(mut c,mut r)=child(&d,if after{"after"}else{"normal"},"kill-key")?;if after {go(&mut c)?;let mut line=String::new();r.read_line(&mut line)?;ensure!(line.starts_with("COMMITTED"),"after commit notification");line.clear();r.read_line(&mut line)?;ensure!(line.starts_with("READY after"),"after commit barrier");}c.kill()?;ensure!(c.wait()?.signal()==Some(9),"actual owned child SIGKILL");check(&d,usize::from(after))?;println!("PASS {name}: actual SIGKILL yields {} with integrity ok",if after{"complete1251"}else{"old uninitialized"});}
 Ok(()) }
